import crypto from 'crypto';
import fs from 'fs';
import path from 'path';
import { CONTEXT_ASSET_MAX_ITEMS } from './contracts';
import type {
  ContextAssetInput,
  StagedContextAsset,
  VariantAssignedWorkspace,
  WorkspaceContextAsset,
} from './contracts';
import { AgentVariantsError } from './errors';
import { isPathWithinRoot } from '../utils/pathContainment';

export const MAX_CONTEXT_ASSET_BYTES = 50 * 1024 * 1024;
export const MAX_CONTEXT_ASSET_TOTAL_BYTES = 100 * 1024 * 1024;
export type ContextAssetPreviewKind = 'static_artifact' | 'dev_server';

const MIME_TYPE_BY_EXTENSION = new Map([
  ['.woff', 'font/woff'],
  ['.woff2', 'font/woff2'],
  ['.ttf', 'font/ttf'],
  ['.otf', 'font/otf'],
  ['.eot', 'application/vnd.ms-fontobject'],
  ['.svg', 'image/svg+xml'],
  ['.png', 'image/png'],
  ['.jpg', 'image/jpeg'],
  ['.jpeg', 'image/jpeg'],
  ['.webp', 'image/webp'],
  ['.gif', 'image/gif'],
  ['.avif', 'image/avif'],
  ['.mp4', 'video/mp4'],
  ['.webm', 'video/webm'],
  ['.mov', 'video/quicktime'],
  ['.mp3', 'audio/mpeg'],
  ['.wav', 'audio/wav'],
  ['.ogg', 'audio/ogg'],
  ['.m4a', 'audio/mp4'],
  ['.pdf', 'application/pdf'],
]);

type ContextAssetSource = {
  resolvedPath: string;
  originalFilename: string;
  extension: string;
  sizeBytes: number;
};

const safeFilename = (value: string): string => {
  const parsed = path.parse(value);
  const base = parsed.name
    .replace(/[^a-zA-Z0-9_-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 64)
    .toLowerCase();
  return `${base || 'asset'}${parsed.ext.toLowerCase()}`;
};

const sha256File = (filePath: string): string => {
  const hash = crypto.createHash('sha256');
  hash.update(fs.readFileSync(filePath));
  return hash.digest('hex');
};

export const inspectContextAssetSource = (
  input: ContextAssetInput,
): ContextAssetSource => {
  const absolutePath = path.resolve(input.path);
  let sourceStat: fs.Stats;
  try {
    sourceStat = fs.lstatSync(absolutePath);
  } catch {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_INVALID',
      `Context asset is not readable: ${input.path}`,
    );
  }
  if (sourceStat.isSymbolicLink()) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_INVALID',
      `Context asset must not be a symlink: ${input.path}`,
    );
  }
  if (!sourceStat.isFile()) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_INVALID',
      `Context asset must be a regular file: ${input.path}`,
    );
  }

  const resolvedPath = fs.realpathSync(absolutePath);
  const originalFilename = path.basename(resolvedPath);
  const extension = path.extname(resolvedPath).toLowerCase();
  if (sourceStat.size === 0 || sourceStat.size > MAX_CONTEXT_ASSET_BYTES) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_TOO_LARGE',
      `Context asset must be 1 byte – ${MAX_CONTEXT_ASSET_BYTES} bytes: ${input.path}`,
    );
  }

  return {
    resolvedPath,
    originalFilename,
    extension,
    sizeBytes: sourceStat.size,
  };
};

export const stageContextAssets = (args: {
  assets: ContextAssetInput[];
  contextBundlePath: string;
}): StagedContextAsset[] => {
  if (args.assets.length > CONTEXT_ASSET_MAX_ITEMS) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_INVALID',
      `Context assets exceed item limit (${args.assets.length} > ${CONTEXT_ASSET_MAX_ITEMS})`,
    );
  }
  const inspected = args.assets.map((asset) => ({
    input: asset,
    source: inspectContextAssetSource(asset),
  }));
  const uniquePaths = new Set(
    inspected.map(({ source }) => source.resolvedPath),
  );
  if (uniquePaths.size !== inspected.length) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_INVALID',
      'Context assets contain duplicate source paths.',
    );
  }
  const totalBytes = inspected.reduce(
    (total, { source }) => total + source.sizeBytes,
    0,
  );
  if (totalBytes > MAX_CONTEXT_ASSET_TOTAL_BYTES) {
    throw new AgentVariantsError(
      'SOURCE_CONTEXT_TOO_LARGE',
      `Context assets exceed total size limit (${totalBytes} > ${MAX_CONTEXT_ASSET_TOTAL_BYTES})`,
    );
  }

  const assetDirectory = path.join(args.contextBundlePath, 'assets');
  fs.mkdirSync(assetDirectory, { recursive: true });
  return inspected.map(({ input, source }, index) => {
    const id = `asset-${index + 1}`;
    const filename = `${id}-${safeFilename(source.originalFilename)}`;
    const destination = path.join(assetDirectory, filename);
    fs.copyFileSync(source.resolvedPath, destination);
    const stagedStat = fs.statSync(destination);
    if (!stagedStat.isFile() || stagedStat.nlink !== 1) {
      throw new AgentVariantsError(
        'SOURCE_CONTEXT_INVALID',
        `Staged context asset is not a safe regular file: ${input.path}`,
      );
    }
    return {
      id,
      path: destination,
      originalFilename: source.originalFilename,
      ...(MIME_TYPE_BY_EXTENSION.get(source.extension)
        ? { mimeType: MIME_TYPE_BY_EXTENSION.get(source.extension) }
        : {}),
      sizeBytes: stagedStat.size,
      sha256: sha256File(destination),
      ...(input.label ? { label: input.label } : {}),
    };
  });
};

const assertPathWithinRoot = (candidate: string, root: string): void => {
  if (!isPathWithinRoot(root, candidate)) {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `Context asset destination escapes its workspace: ${candidate}`,
    );
  }
};

const workspaceAssetDestination = (args: {
  workspace: VariantAssignedWorkspace;
  filename: string;
  previewKind: ContextAssetPreviewKind;
}): { workspacePath: string; referencePath: string } => {
  if (args.workspace.kind === 'artifact_directory') {
    return {
      workspacePath: path.join(
        args.workspace.rootPath,
        'assets',
        'rivet',
        args.filename,
      ),
      referencePath: `./assets/rivet/${args.filename}`,
    };
  }
  const hasPublicDirectoryConvention = fs.existsSync(
    path.join(args.workspace.projectPath, 'package.json'),
  );
  const assetDirectory = hasPublicDirectoryConvention
    ? path.join(args.workspace.projectPath, 'public', 'rivet-assets')
    : path.join(args.workspace.projectPath, 'rivet-assets');
  const staticReferenceDirectory = hasPublicDirectoryConvention
    ? 'public/rivet-assets'
    : 'rivet-assets';
  return {
    workspacePath: path.join(assetDirectory, args.filename),
    referencePath:
      args.previewKind === 'static_artifact'
        ? `./${staticReferenceDirectory}/${args.filename}`
        : `/rivet-assets/${args.filename}`,
  };
};

export const materializeContextAssets = (args: {
  assets: StagedContextAsset[];
  workspace: VariantAssignedWorkspace;
  previewKind: ContextAssetPreviewKind;
}): WorkspaceContextAsset[] => {
  fs.mkdirSync(args.workspace.rootPath, { recursive: true });
  const requestedWorkspaceRoot = path.resolve(args.workspace.rootPath);
  const resolvedWorkspaceRoot = fs.realpathSync(args.workspace.rootPath);

  return args.assets.map((asset) => {
    let sourceStat: fs.Stats;
    try {
      sourceStat = fs.lstatSync(asset.path);
    } catch {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Context asset is missing from its staged bundle: ${asset.id}`,
      );
    }
    if (
      sourceStat.isSymbolicLink() ||
      !sourceStat.isFile() ||
      sourceStat.nlink !== 1
    ) {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Context asset is not a safe staged file: ${asset.id}`,
      );
    }
    if (sha256File(asset.path) !== asset.sha256) {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Context asset digest changed after staging: ${asset.id}`,
      );
    }

    const filename = path.basename(asset.path);
    const destination = workspaceAssetDestination({
      workspace: args.workspace,
      filename,
      previewKind: args.previewKind,
    });
    assertPathWithinRoot(
      path.resolve(destination.workspacePath),
      requestedWorkspaceRoot,
    );
    fs.mkdirSync(path.dirname(destination.workspacePath), { recursive: true });
    const resolvedDestinationDirectory = fs.realpathSync(
      path.dirname(destination.workspacePath),
    );
    assertPathWithinRoot(resolvedDestinationDirectory, resolvedWorkspaceRoot);
    fs.copyFileSync(asset.path, destination.workspacePath);
    const destinationStat = fs.lstatSync(destination.workspacePath);
    if (
      destinationStat.isSymbolicLink() ||
      !destinationStat.isFile() ||
      destinationStat.nlink !== 1 ||
      sha256File(destination.workspacePath) !== asset.sha256
    ) {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        `Context asset failed workspace integrity validation: ${asset.id}`,
      );
    }

    return {
      id: asset.id,
      sourcePath: asset.path,
      workspacePath: destination.workspacePath,
      referencePath: destination.referencePath,
      sha256: asset.sha256,
      ...(asset.label ? { label: asset.label } : {}),
    };
  });
};
